import net from 'node:net';
import http from 'node:http';

export const BACKENDS = {
  'node-ts': 3501, deno: 3502, python: 3503, rust: 3504, php: 3505,
  go: 3506, java: 3507, dotnet: 3508, bun: 3509,
};
export const TOK = { alice: 'tok_alice', bob: 'tok_bob', carol: 'tok_carol' };

// High-level request via node:http. opts: {token, headers, body, method, path, timeout}
export function req(port, method, path, { token, headers = {}, body, timeout = 8000, rawBody } = {}) {
  return new Promise((resolve) => {
    const h = { ...headers };
    if (token) h.authorization = `Bearer ${token}`;
    let buf = null;
    if (rawBody !== undefined) buf = Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(rawBody);
    else if (body !== undefined) { buf = Buffer.from(typeof body === 'string' ? body : JSON.stringify(body)); if (h['content-type'] === undefined) h['content-type'] = 'application/json'; }
    if (buf) h['content-length'] = buf.length;
    let done = false; const fin = (v) => { if (!done) { done = true; resolve(v); } };
    const r = http.request({ host: '127.0.0.1', port, method, path, headers: h, agent: false, timeout }, (res) => {
      const ch = []; res.on('data', (c) => ch.push(c));
      res.on('end', () => { const text = Buffer.concat(ch).toString('utf8'); let json; try { json = JSON.parse(text); } catch {} fin({ status: res.statusCode, headers: res.headers, text, json }); });
      res.on('error', (e) => setTimeout(() => fin({ error: String(e) }), 100));
    });
    r.on('timeout', () => { r.destroy(); fin({ error: 'timeout' }); });
    r.on('error', (e) => setTimeout(() => fin({ error: String(e) }), 100));
    if (buf) r.write(buf); r.end();
  });
}

// Raw socket request: full control over bytes. Returns {status, headersText, body, raw}
export function rawReq(port, payload, { timeout = 8000 } = {}) {
  return new Promise((resolve) => {
    const sock = net.connect(port, '127.0.0.1');
    let data = Buffer.alloc(0); let done = false;
    const fin = (v) => { if (!done) { done = true; try { sock.destroy(); } catch {} resolve(v); } };
    sock.setTimeout(timeout);
    sock.on('connect', () => sock.write(Buffer.isBuffer(payload) ? payload : Buffer.from(payload)));
    sock.on('data', (c) => { data = Buffer.concat([data, c]); });
    sock.on('end', () => { const s = data.toString('latin1'); const m = s.match(/HTTP\/1\.[01] (\d+)/); fin({ status: m ? +m[1] : null, raw: s }); });
    sock.on('timeout', () => fin({ status: 'timeout', raw: data.toString('latin1') }));
    sock.on('error', (e) => fin({ status: 'error', err: String(e), raw: data.toString('latin1') }));
  });
}

export async function createTeam(port, token, id, name = 'T') {
  return req(port, 'POST', '/teams', { token, body: { id, name } });
}
export async function createNote(port, token, teamId, title = 'hi', body) {
  const b = { title }; if (body !== undefined) b.body = body;
  return req(port, 'POST', `/teams/${teamId}/notes`, { token, body: b });
}
export function uniq(p) { return `${p}${Date.now().toString(36)}${Math.floor(Math.random()*1e4)}`; }

