import { BACKENDS, TOK, req, rawReq, createTeam, createNote, uniq } from './lib.mjs';

const name = process.argv[2];
const port = BACKENDS[name];
if (!port) { console.error('unknown backend', name); process.exit(2); }
const R = []; // results
function rec(id, sev, card, expected, pass, detail) { R.push({ id, sev, card, expected, pass, detail }); }

const A = TOK.alice, B = TOK.bob, C = TOK.carol;

async function main() {
  // ---------- 1. AUTHZ / privilege escalation ----------
  // bob (member of team-red) adds carol -> 403
  {
    const r = await req(port, 'PUT', '/teams/team-red/members/carol', { token: B });
    rec('authz.bob-add-carol', 'critical', 'TEAM-3', '403', r.status === 403, `status=${r.status}`);
  }
  // bob removes alice (owner) -> 403
  {
    const r = await req(port, 'DELETE', '/teams/team-red/members/alice', { token: B });
    rec('authz.bob-remove-alice', 'critical', 'TEAM-3', '403', r.status === 403, `status=${r.status}`);
    // verify alice still owner
    const me = await req(port, 'GET', '/teams/team-red', { token: A });
    rec('authz.bob-remove-alice.effect', 'critical', 'TEAM-3', 'alice still owner', me.status === 200 && me.json?.role === 'owner', `status=${me.status} role=${me.json?.role}`);
  }
  // bob adds himself as member again (idempotent add) but can he escalate role? PUT only -> member. Check role stays member.
  {
    const r = await req(port, 'PUT', '/teams/team-red/members/bob', { token: A }); // alice re-adds bob (idempotent)
    rec('authz.readd-bob-role', 'high', 'TEAM-3', 'role=member', r.status === 200 ? r.json?.role === 'member' : true, `status=${r.status} role=${r.json?.role}`);
  }
  // carol (owner of team-blue, non-member of team-red) touches team-red through every route -> 404
  const redNote = await createNote(port, A, 'team-red', 'alice-secret');
  const redNoteId = redNote.json?.id;
  for (const [route, m, p, body] of [
    ['carol-list-red', 'GET', '/teams/team-red/notes'],
    ['carol-create-red', 'POST', '/teams/team-red/notes', { title: 'x' }],
    ['carol-archived-red', 'GET', '/teams/team-red/notes?archived=true'],
    ['carol-get-team-red', 'GET', '/teams/team-red'],
    ['carol-members-red', 'GET', '/teams/team-red/members'],
    ['carol-put-member-red', 'PUT', '/teams/team-red/members/carol'],
    ['carol-del-member-red', 'DELETE', '/teams/team-red/members/alice'],
    ['carol-get-rednote', 'GET', `/notes/${redNoteId}`],
    ['carol-patch-rednote', 'PATCH', `/notes/${redNoteId}`, { title: 'z' }],
    ['carol-del-rednote', 'DELETE', `/notes/${redNoteId}`],
    ['carol-restore-rednote', 'POST', `/notes/${redNoteId}/restore`],
  ]) {
    const o = { token: C }; if (body) { o.body = body; if (m === 'PATCH') o.headers = { 'if-match': '"1"' }; }
    const r = await req(port, m, p, o);
    rec('isolation.' + route, 'critical', 'AUTHZ-1/2/TEAM-3/5', '404', r.status === 404, `status=${r.status}`);
  }
  // carol must never see red note id in any body
  {
    const leaks = R.filter((x) => x.id.startsWith('isolation.carol') && redNoteId && x.detail.includes(redNoteId));
    rec('isolation.no-id-leak', 'critical', 'I3', 'no red id in carol responses', leaks.length === 0, `leaks=${leaks.length}`);
  }

  // ---------- team id collision ----------
  // create "team-red" again -> 409, and carol gains nothing
  {
    const r = await createTeam(port, C, 'team-red', 'Hijack');
    const ok = r.status === 409;
    rec('collision.exact-dup', 'critical', 'TEAM-2', '409', ok, `status=${r.status}`);
    const after = await req(port, 'GET', '/teams/team-red/notes', { token: C });
    rec('collision.exact-dup.effect', 'critical', 'TEAM-2', 'carol still 404 on team-red', after.status === 404, `status=${after.status}`);
  }
  // case-variant / unicode / whitespace collisions -> 422 (not in slug charset) OR distinct id
  for (const [cid, slug] of [['Team-Red', 'Team-Red'], ['ws-trail', 'team-red '], ['ws-lead', ' team-red'], ['unicode', 'team‐red'], ['fullwidth', 'ｔｅａｍ-red']]) {
    const r = await createTeam(port, C, slug, 'X');
    // Any status that is NOT 422 and NOT (201 of a genuinely distinct, non-colliding id) is suspicious.
    // All these slugs violate ^[a-z0-9-]{3,40}$ -> must be 422.
    const ok = r.status === 422;
    rec('collision.' + cid, 'high', 'TEAM-2', '422 (invalid slug)', ok, `slug=${JSON.stringify(slug)} status=${r.status}`);
    if (r.status === 201) {
      // did it grant access to team-red? check
      const acc = await req(port, 'GET', '/teams/team-red/notes', { token: C });
      rec('collision.' + cid + '.access', 'critical', 'AUTHZ-2', 'no access to team-red', acc.status === 404, `status=${acc.status}`);
    }
  }

  // ---------- 3. tenant isolation: note id in members path ----------
  {
    const r = await req(port, 'PUT', `/teams/team-red/members/${redNoteId}`, { token: A });
    rec('isolation.noteid-as-member', 'medium', 'TEAM-3', '422 (unknown userId)', r.status === 422, `status=${r.status}`);
  }
  // 404 vs 403 body identity: non-member note ops all identical to random uuid
  {
    const rand = await req(port, 'GET', '/notes/00000000-0000-0000-0000-000000000000', { token: C });
    const malformed = await req(port, 'GET', '/notes/not-a-uuid', { token: C });
    const other = await req(port, 'GET', `/notes/${redNoteId}`, { token: C });
    const same = rand.text === malformed.text && rand.text === other.text;
    rec('isolation.404-byte-identical', 'high', 'AUTHZ-3', 'byte-identical 404 bodies', same && rand.status === 404, `rand=${rand.status} malformed=${malformed.status} other=${other.status} same=${same}`);
  }

  // ---------- 4. injection / parsing ----------
  // SQL metachars round-trip in title (alice on team-red)
  const sqlPayloads = ["' OR 1=1--", "'; DROP TABLE notes;--", "%27", "a\u0000b", "x".repeat(0) + "admin'--"];
  for (const [i, pl] of sqlPayloads.entries()) {
    const r = await createNote(port, A, 'team-red', pl, 'b');
    if (r.status === 201) {
      const back = await req(port, 'GET', `/notes/${r.json.id}`, { token: A });
      const rt = back.json?.title === pl;
      rec('inject.sql-rt-' + i, 'high', 'FMT-3', 'round-trips exactly, no 5xx', rt && back.status === 200, `status=${r.status}/${back.status} roundtrip=${rt} got=${JSON.stringify(back.json?.title)}`);
    } else {
      // NUL title a\u0000b should be accepted per FMT-3; others ok to accept
      rec('inject.sql-rt-' + i, 'high', 'FMT-3', 'accepted(201) & round-trip', r.status === 201, `status=${r.status}`);
    }
  }
  // verify notes table still exists (list works)
  {
    const r = await req(port, 'GET', '/teams/team-red/notes', { token: A });
    rec('inject.table-intact', 'critical', 'SQLi', 'list still works', r.status === 200, `status=${r.status}`);
  }
  // NUL in body round-trip (FMT-3 Deno truncation)
  {
