  {
    const r = await req(port, 'PUT', `/teams/team-red/members/${redNoteId}`, { token: A });
    rec('isolation.noteid-as-member', 'medium', 'TEAM-3', '422 (unknown userId)', r.status === 422, `status=${r.status}`);
