    const r = await req(port, 'POST', '/teams/team-red/notes', { token: A, rawBody: Buffer.concat([pre, mid, post]), headers: { 'content-type': 'application/json' } });
    rec('inject.raw-bad-utf8', 'medium', 'FMT-3', '400', r.status === 400, `status=${r.status}`);
  }
