  for (const [cid, raw] of [['proto', '{"title":"t","__proto__":{"x":1}}'], ['ctor', '{"title":"t","constructor":{"y":1}}']]) {
    const r = await req(port, 'POST', '/teams/team-red/notes', { token: A, body: raw });
    rec('inject.' + cid, 'medium', 'VALID-3', '422', r.status === 422, `status=${r.status}`);
  }
  // deep nesting (not an object field, body itself huge nesting) -> 400 or 422, no 5xx/crash
  {
    const deep = '{"title":"t","body":' + '['.repeat(5000) + '1' + ']'.repeat(5000) + '}';
    const r = await req(port, 'POST', '/teams/team-red/notes', { token: A, body: deep });
    rec('inject.deep-nest', 'medium', 'JSON', 'no 5xx', r.status && r.status < 500, `status=${r.status || r.error}`);
  }
