import { BACKENDS, TOK, req, createTeam, createNote, uniq } from './lib.mjs';
const A = TOK.alice, B = TOK.bob;

async function one(name, port) {
  const tid = uniq('race');
  await createTeam(port, A, tid, 'Race');
  await req(port, 'PUT', `/teams/${tid}/members/bob`, { token: A });
  const note = await createNote(port, B, tid, 'bob-note', 'x');
  const id = note.json?.id;
  if (!id) return { name, error: 'no note', note };

  // Phase 1: fire DELETE(bob) concurrently with 20 PATCHes from bob (all If-Match "1").
  const promises = [];
  const delP = req(port, 'DELETE', `/teams/${tid}/members/bob`, { token: A });
  for (let i = 0; i < 20; i++) promises.push(req(port, 'PATCH', `/notes/${id}`, { token: B, headers: { 'if-match': '"1"' }, body: { title: `p${i}` } }));
  const del = await delP;
  const patches = await Promise.all(promises);
  const counts = {};
  for (const p of patches) counts[p.status || p.error] = (counts[p.status || p.error] || 0) + 1;

  // Phase 2 (strict): bob is definitively removed now. Any later write MUST be 404.
  // Need a fresh ETag; owner reads current version.
  const cur = await req(port, 'GET', `/notes/${id}`, { token: A });
  const etag = cur.headers?.etag;
  const post = await Promise.all(Array.from({ length: 10 }, (_, i) =>
    req(port, 'PATCH', `/notes/${id}`, { token: B, headers: { 'if-match': etag || '"2"' }, body: { title: `post${i}` } })));
  const postCounts = {};
  for (const p of post) postCounts[p.status || p.error] = (postCounts[p.status || p.error] || 0) + 1;
  // also POST and DELETE by bob post-removal
  const postPost = await req(port, 'POST', `/teams/${tid}/notes`, { token: B, body: { title: 'sneak' } });
  const postDel = await req(port, 'DELETE', `/notes/${id}`, { token: B });

  // integrity: final version should equal 1 + (# of 200 patches in phase1) ; no 404-after-204 writes succeeded
  const final = await req(port, 'GET', `/notes/${id}`, { token: A });
  const p1_200 = counts['200'] || 0;
  const expectedVer = 1 + p1_200;
  const verOk = final.json?.version === expectedVer;

  const strictViolations = (postCounts['200'] || 0) + (postPost.status === 201 ? 1 : 0) + (postDel.status === 204 ? 1 : 0);

  return {
    name, id, delStatus: del.status, phase1: counts, phase1_version_ok: verOk, final_version: final.json?.version, expectedVer,
    phase2_postRemoval: postCounts, postPost: postPost.status, postDelete: postDel.status, strictViolations,
  };
}

const results = [];
for (const [name, port] of Object.entries(BACKENDS)) {
  try { results.push(await one(name, port)); } catch (e) { results.push({ name, error: String(e) }); }
}
for (const r of results) {
  const bad = r.strictViolations > 0 || r.phase1_version_ok === false || r.error;
  console.log((bad ? 'VIOLATION ' : 'ok        ') + r.name.padEnd(8),
    'del=' + r.delStatus, 'p1=' + JSON.stringify(r.phase1), 'verOk=' + r.phase1_version_ok + '(' + r.final_version + '/' + r.expectedVer + ')',
    'p2removed=' + JSON.stringify(r.phase2_postRemoval), 'postPOST=' + r.postPost, 'postDEL=' + r.postDelete, 'strictViol=' + r.strictViolations, r.error || '');
}
console.log('\nJSON', JSON.stringify(results));

