// Hypothesis A: response-before-body-consumed RST. Send a POST to GET-only route /health with a body, new socket each.
// Hypothesis B: rapid connection churn.
async function test(name, port){
  let hangA=0, okA=0;
  // A: POST /health with body (handler ignores body) x200
  for(let i=0;i<200;i++){ const r=await req(port,'POST','/health?x=1',{token:'tok_alice',body:{title:'x'},timeout:4000}); if(r.error)hangA++; else okA++; }
  // A2: GET-only route with large unread body: DELETE /teams/team-red/notes?archived[]=true with body
  let hangC=0;
  for(let i=0;i<100;i++){ const r=await req(port,'GET','/notes/__proto__',{token:'tok_bob',headers:{'if-match':'*'},timeout:4000}); if(r.error)hangC++; }
  return {name, hangA, okA, hangC};
}
for(const [n,p] of Object.entries(BACKENDS)) console.log(JSON.stringify(await test(n,p)));
EOF
node churn.mjs

