import { BACKENDS, rawReq } from './lib.mjs';
for (const [name, port] of Object.entries(BACKENDS)) {
  // HEAD on a 404 route (random uuid) with token
  const p = `HEAD /notes/00000000-0000-0000-0000-000000000000 HTTP/1.1\r\nHost: x\r\nAuthorization: Bearer tok_alice\r\nConnection: close\r\n\r\n`;
  const r = await rawReq(port, p, { timeout: 4000 });
  const raw = r.raw || '';
  const hdrEnd = raw.indexOf('\r\n\r\n');
  const head = hdrEnd >= 0 ? raw.slice(0, hdrEnd) : raw;
  const bodyBytes = hdrEnd >= 0 ? raw.length - hdrEnd - 4 : 0;
  const cl = (head.match(/content-length:\s*(\d+)/i) || [])[1];
  console.log(name.padEnd(8), 'status=' + r.status, 'CL=' + cl, 'bytesAfterHeaders=' + bodyBytes, bodyBytes > 0 ? 'BODY-ON-HEAD!' : 'ok');
}
EOF
node head.mjs

