import { req } from './lib.mjs';
const cases = ['/%E0%A4%A','/%E0','/%','/%zz','/notes/%00','/notes/%ff','/notes/x%00y','/%00','/teams/%00/notes','/notes/a?x=%ff','/notes/a?x=%00'];
