  console.log('### '+name);
  for(const p of cases){
    const a = await req(port,'GET',p,{token:'tok_alice',timeout:3000});
    const n = await req(port,'GET',p,{timeout:3000}); // no token
    const ac=(a.headers?.['content-type']||'-').split(';')[0];
    const flag = (n.status!==401 || a.status>=500 || n.status>=500)?'  <-- AUTHN/ERR issue':'';
    console.log('  '+p.padEnd(22)+' authed='+(a.status||a.error)+'/'+ac+'  notoken='+(n.status||n.error)+flag);
  }
}
EOF
node malpath.mjs

